    var ks = issuesOf(p).map(function (x) { return x.k; }), rule = ['returned', 'damlost', 'pickup', 'failed', 'noscan'].filter(function (k) { return ks.indexOf(k) >= 0; })[0] || 'manual';
    if (stE.rule && ks.indexOf(stE.rule) >= 0 && route.base === 'exceptions') rule = stE.rule; // the queue is filtered on one rule
    var kind = MSG.kindFor(rule, p.status), pk = pickupInfo(p);
