  // ════════════════════════════════════════════════════════════════════════
  // Search
  // ════════════════════════════════════════════════════════════════════════
  function searchHits(q) {
    var n = norm(q).trim(); if (n.length < 2) return [];
    var words = n.split(/\s+/), compact = n.replace(/\s+/g, '');
    return G.parcels.filter(function (p) {
      if (p.tracking.toLowerCase() === compact || p.order.toLowerCase() === compact) return true;
      return words.every(function (w) { return p.key.indexOf(w) >= 0; }) || (compact.length >= 5 && p.key.replace(/\s+/g, '').indexOf(compact) >= 0);
    }).sort(function (a, b) { return a.created < b.created ? 1 : -1; });
  }
  function hl(text, q) {
    var t = String(text), n = norm(t), words = norm(q).trim().split(/\s+/).filter(function (w) { return w.length >= 2; }), marks = [];
    words.forEach(function (w) { var i = n.indexOf(w); if (i >= 0) marks.push([i, i + w.length]); });
    if (!marks.length) return esc(t);
    marks.sort(function (a, b) { return a[0] - b[0]; });
    var out = '', pos = 0;
    marks.forEach(function (m) { if (m[0] < pos) return; out += esc(t.slice(pos, m[0])) + '<mark>' + esc(t.slice(m[0], m[1])) + '</mark>'; pos = m[1]; });
    return out + esc(t.slice(pos));
  }
