    if (IMP.kind === 'carrier' && miss.length === 1 && miss[0] === 'Amount paid out' && IMP.map.cod >= 0) miss = [];
    if (miss.length) { IMP.err = 'Choose a column for: ' + miss.join(', ') + '.'; withFocus(renderPage); return; }
    IMP.err = '';
    st.recon.maps[impMapKey()] = { cols: I.mapToSaved(IMP.headers, IMP.map), dec: IMP.dec, delim: IMP.delim === '\t' ? 'tab' : IMP.delim };
